"""Vendor maintenance log parser with proper error handling."""

import csv
import sys


def summarize(path: str) -> dict[str, int]:
    counts = {"ok": 0, "malformed": 0, "high": 0}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            # Fix Bug 1: Check if temperature_c exists and is not empty
            temp_str = row.get("temperature_c", "")
            if temp_str == "":
                counts["malformed"] += 1
                continue

            temperature = float(temp_str)

            # Fix Bug 2: 350.0 is the inclusive upper limit, so it's OK
            # Only temperatures strictly greater than 350.0 are high
            if temperature > 350.0:
                counts["high"] += 1
            else:
                counts["ok"] += 1
    return counts


if __name__ == "__main__":
    print(summarize(sys.argv[1]))
